using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.Refresh(ImportAssetOptions.ForceUpdate);
        AssetDatabase.SaveAssets();
        // Trigger the install
        Homesteader.UI.EditorTools.HudWiringMenu.Install();
        var hud = GameObject.Find("HudRoot");
        if (hud != null)
        {
            var comps = hud.GetComponents<Component>();
            result.Log("HudRoot now has " + comps.Length + " components:");
            foreach (var c in comps)
            {
                result.Log("  " + (c == null ? "null" : c.GetType().Name));
            }
            // Save the scene so changes persist.
            var scn = SceneManager.GetActiveScene();
            if (scn.IsValid())
            {
                EditorSceneManager.SaveScene(scn);
                result.Log("Saved scene: " + scn.path);
            }
        }
        else
        {
            result.Log("HudRoot still missing.");
        }
    }
}
